--
-- V4 :: Indexes for the review and access-control query paths.
--
-- The baseline was generated by ddl-auto, which creates primary keys and
-- unique constraints but no secondary indexes at all. Every query below was
-- therefore running a sequential scan.
--
-- CONCURRENTLY is intentionally NOT used: these tables are small, and it
-- cannot run inside Flyway's transaction.
--

-- ---------------------------------------------------------------------------
-- Review queue.
--
-- findPendingForReviewer / findPendingForReviewerInScope filter on status and
-- then match on either reviewer_id or the KPI owner. Separate indexes let the
-- planner bitmap-OR the two branches rather than scan the table.
-- ---------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_kpis_status ON public.kpis (status);
CREATE INDEX IF NOT EXISTS idx_kpis_reviewer_status ON public.kpis (reviewer_id, status);
CREATE INDEX IF NOT EXISTS idx_kpis_user_cycle ON public.kpis (user_id, review_cycle_id);

-- The reminder sweep scans for KPIs sitting in a review state past a cutoff.
-- Partial on NOT NULL because unsubmitted KPIs are irrelevant to it and are
-- the bulk of the table early in a cycle.
CREATE INDEX IF NOT EXISTS idx_kpis_status_submitted_at
    ON public.kpis (status, submitted_at)
    WHERE submitted_at IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Org hierarchy expansion (AccessControlService).
--
-- The *_leads join tables have a composite primary key of (<org>_id, user_id).
-- Lookups go the other way -- "which squads does this user lead?" -- which the
-- PK cannot serve because user_id is not its leading column.
-- ---------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_squad_leads_user ON public.squad_leads (user_id);
CREATE INDEX IF NOT EXISTS idx_portfolio_leads_user ON public.portfolio_leads (user_id);
CREATE INDEX IF NOT EXISTS idx_tribe_leads_user ON public.tribe_leads (user_id);

CREATE INDEX IF NOT EXISTS idx_user_squad_assign_squad ON public.user_squad_assignments (squad_id);
CREATE INDEX IF NOT EXISTS idx_user_squad_assign_user ON public.user_squad_assignments (user_id);
CREATE INDEX IF NOT EXISTS idx_user_portfolio_assign_user ON public.user_portfolio_assignments (user_id);
CREATE INDEX IF NOT EXISTS idx_user_tribe_assign_user ON public.user_tribe_assignments (user_id);

-- Tribe -> portfolios -> squads descent.
CREATE INDEX IF NOT EXISTS idx_squads_portfolio ON public.squads (portfolio_id);
CREATE INDEX IF NOT EXISTS idx_portfolios_tribe ON public.portfolios (tribe_id);

-- ---------------------------------------------------------------------------
-- Reporting line. Used to answer "is this reviewer the employee's manager?" on
-- every single review authorisation check.
-- ---------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_users_reporting_manager ON public.users (reporting_manager_id);

-- ---------------------------------------------------------------------------
-- Detail loads.
-- ---------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_kpi_evidences_kpi ON public.kpi_evidences (kpi_id);
CREATE INDEX IF NOT EXISTS idx_kpi_scorecards_user_cycle ON public.kpi_scorecards (user_id, review_cycle_id);
CREATE INDEX IF NOT EXISTS idx_kpi_assignments_user ON public.kpi_assignments (user_id);

